package dev.konqasasas.beat.application;import dev.konqasasas.beat.domain.*;import dev.konqasasas.beat.domain.endurance.*;import dev.konqasasas.beat.persistence.*;import dev.konqasasas.beat.persistence.snapshot.*;import java.util.*;
public final class EnduranceResultService{private final ResultsRepository repository;public EnduranceResultService(ResultsRepository r){repository=r;}public ResultsSnapshot saveFinal(EnduranceSession s)throws PersistenceException{var c=current();Map<UUID,PlayerResultSnapshot> old=new LinkedHashMap<>();c.players().forEach(p->old.put(p.uuid(),p));List<PlayerResultSnapshot> out=new ArrayList<>();s.rankings().forEach(e->{var p=old.remove(e.competitor().uuid());var r=e.record();out.add(new PlayerResultSnapshot(e.competitor().uuid(),e.competitor().tournamentName(),p!=null&&p.participatedHigh(),p!=null&&p.participatedTa(),e.competitor().participatedIn(CompetitionKind.ENDURANCE),p!=null&&p.overallExcluded(),p!=null&&p.disqualified(),p==null?null:p.high(),p==null?null:p.timeAttack(),new EnduranceResultSnapshot(e.rank(),r.maxProgress(),r.maxProgressReachedTick().isPresent()?r.maxProgressReachedTick().getAsLong():null,r.zone2Reached(),r.zone3Reached(),r.goalReached()),null));});out.addAll(old.values());var saved=new ResultsSnapshot(c.schemaVersion(),c.highConfirmed(),c.timeAttackConfirmed(),true,false,out);repository.save(saved);return saved;}public ResultsSnapshot current()throws PersistenceException{return repository.load().orElse(new ResultsSnapshot(1,false,false,false,false,List.of()));}}
